import json,subprocess,datetime,sqlite3

def emit(k,d):print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'kind':k,'data':d},ensure_ascii=False))
def sql(q):
 r=subprocess.run(['docker','exec','-i','adobe-relay-postgres-1','psql','-U','sub2api','-d','sub2api','-Atq','-v','ON_ERROR_STOP=1'],input="BEGIN READ ONLY;SET LOCAL statement_timeout='35s';"+q+';COMMIT;',capture_output=True,text=True,timeout=45)
 if r.returncode:raise RuntimeError('read_query_failed')
 return [json.loads(x) for x in r.stdout.splitlines() if x.startswith('{')]
emit('application',[{'name':n,'image':(x:=json.loads(subprocess.check_output(['docker','inspect',n],text=True))[0])['Config']['Image'],'image_id':x['Image'],'restarts':x['RestartCount'],'started':x['State']['StartedAt']} for n in ['adobe-relay-app-1','adobe-team-cookie-app-1']])
emit('status_totals',sql("SELECT json_build_object('status',status,'schedulable',schedulable,'count',count(*),'with_source_cookie',count(NULLIF(credentials->>'cookie','')),'with_runtime_cookie',count(NULLIF(credentials->>'adobe_session_cookie','')),'with_token',count(NULLIF(credentials->>'access_token',''))) FROM accounts WHERE platform='adobe' AND deleted_at IS NULL GROUP BY status,schedulable"))
emit('errors_by_hour',sql("SELECT json_build_object('hour',date_trunc('hour',created_at),'status',status_code,'upstream_status',upstream_status_code,'phase',error_phase,'model',model,'count',count(*),'accounts',count(DISTINCT account_id)) FROM ops_error_logs WHERE platform='adobe' AND created_at>=now()-interval '30 hours' GROUP BY 1::int,date_trunc('hour',created_at),status_code,upstream_status_code,error_phase,model ORDER BY date_trunc('hour',created_at)".replace('GROUP BY 1::int,','GROUP BY ')))
emit('408_signature',sql("SELECT json_build_object('signature',CASE WHEN coalesce(upstream_error_message,'') ILIKE '%system under load%' THEN 'system_under_load' WHEN coalesce(upstream_error_message,'') ILIKE '%timeout_error%' THEN 'timeout_error' ELSE 'other' END,'count',count(*),'median_latency_ms',percentile_cont(0.5) WITHIN GROUP(ORDER BY upstream_latency_ms),'accounts',count(DISTINCT account_id)) FROM ops_error_logs WHERE platform='adobe' AND upstream_status_code=408 AND created_at>=now()-interval '30 hours' GROUP BY 1::int,CASE WHEN coalesce(upstream_error_message,'') ILIKE '%system under load%' THEN 'system_under_load' WHEN coalesce(upstream_error_message,'') ILIKE '%timeout_error%' THEN 'timeout_error' ELSE 'other' END".replace('GROUP BY 1::int,','GROUP BY ')))
emit('408_upstream_events',sql("SELECT json_build_object('at',l.created_at,'account_id',l.account_id,'model',l.model,'status',l.upstream_status_code,'proxy_id',e->'proxy_id','stage',e->'stage','stage_attempts',CASE WHEN e->>'detail' LIKE '{%' THEN (e->>'detail')::jsonb->'stage_attempts' ELSE NULL END,'stage_elapsed_ms',CASE WHEN e->>'detail' LIKE '{%' THEN (e->>'detail')::jsonb->'stage_elapsed_ms' ELSE NULL END,'load_message',coalesce(e->>'message','') ILIKE '%system under load%','timeout_code',coalesce(e->>'message','') ILIKE '%timeout_error%') FROM ops_error_logs l CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(l.upstream_errors)='array' THEN l.upstream_errors ELSE '[]'::jsonb END) e WHERE l.platform='adobe' AND l.upstream_status_code=408 AND l.created_at>=now()-interval '30 hours' ORDER BY l.created_at DESC LIMIT 2000"))
candidates=sql("SELECT json_build_object('id',a.id,'name',a.name,'status',a.status,'schedulable',a.schedulable,'proxy_id',a.proxy_id,'concurrency',a.concurrency,'groups',(SELECT json_agg(group_id) FROM account_groups WHERE account_id=a.id),'manual_pause',a.extra->'okad_manual_pause','manual_proxy',a.extra->'manual_proxy_enabled','okad',jsonb_build_object('issuer',a.extra->'okad'->'issuer','source_key',a.extra->'okad'->'source_key','verification',a.extra->'okad'->'verification'),'test_state',a.extra->'okad_connection_test'->'state','cookie_sha',md5(a.credentials->>'cookie'),'has_token',NULLIF(a.credentials->>'access_token','') IS NOT NULL,'expires_at',a.credentials->>'expires_at','recent',x.data,'successes',u.c,'last_success',u.last_at) FROM accounts a LEFT JOIN LATERAL (SELECT jsonb_build_object('408',count(*) FILTER(WHERE upstream_status_code=408),'401',count(*) FILTER(WHERE upstream_status_code=401),'429',count(*) FILTER(WHERE upstream_status_code=429),'last408',max(created_at) FILTER(WHERE upstream_status_code=408),'last401',max(created_at) FILTER(WHERE upstream_status_code=401)) data FROM ops_error_logs WHERE account_id=a.id AND created_at>=now()-interval '30 hours') x ON true LEFT JOIN LATERAL (SELECT count(*) c,max(created_at) last_at FROM usage_logs WHERE account_id=a.id AND created_at>=now()-interval '30 hours') u ON true WHERE a.platform='adobe' AND a.deleted_at IS NULL ORDER BY (x.data->>'408')::bigint DESC LIMIT 80")
emit('candidate_accounts',candidates)
c=sqlite3.connect('file:/opt/adobe-team-cookie/data/app.db?mode=ro',uri=True);c.row_factory=sqlite3.Row
names=[x['name'].lower() for x in candidates];emit('okad_mapping',[dict(r) for r in c.execute('SELECT id,email,last_login_at FROM external_members WHERE lower(email) IN ('+','.join('?' for _ in names)+')',names)]);c.close()
